#pragma once
/* THE SMALLEST FAUST ARCHITECTURE: what a class generated by `faust -lang cpp
 * -scn FaustDsp` needs to compile, and nothing else — no audio driver, no GUI.
 * The firmware calls compute() itself, from the audio task, and finds each
 * parameter by its label (FaustParams). */
#include <cstring>

#ifndef FAUSTFLOAT
#define FAUSTFLOAT float
#endif

struct Soundfile;

struct Meta {
  virtual ~Meta() {}
  virtual void declare(const char*, const char*) {}
};

struct UI {
  virtual ~UI() {}
  virtual void openTabBox(const char*) {}
  virtual void openHorizontalBox(const char*) {}
  virtual void openVerticalBox(const char*) {}
  virtual void closeBox() {}
  virtual void addButton(const char* label, FAUSTFLOAT* zone) { addParam(label, zone); }
  virtual void addCheckButton(const char* label, FAUSTFLOAT* zone) { addParam(label, zone); }
  virtual void addVerticalSlider(const char* label, FAUSTFLOAT* zone, FAUSTFLOAT, FAUSTFLOAT, FAUSTFLOAT, FAUSTFLOAT) { addParam(label, zone); }
  virtual void addHorizontalSlider(const char* label, FAUSTFLOAT* zone, FAUSTFLOAT, FAUSTFLOAT, FAUSTFLOAT, FAUSTFLOAT) { addParam(label, zone); }
  virtual void addNumEntry(const char* label, FAUSTFLOAT* zone, FAUSTFLOAT, FAUSTFLOAT, FAUSTFLOAT, FAUSTFLOAT) { addParam(label, zone); }
  virtual void addHorizontalBargraph(const char*, FAUSTFLOAT*, FAUSTFLOAT, FAUSTFLOAT) {}
  virtual void addVerticalBargraph(const char*, FAUSTFLOAT*, FAUSTFLOAT, FAUSTFLOAT) {}
  virtual void addSoundfile(const char*, const char*, Soundfile**) {}
  virtual void declare(FAUSTFLOAT*, const char*, const char*) {}
  virtual void addParam(const char*, FAUSTFLOAT*) {}
};

class FaustDsp {
 public:
  virtual ~FaustDsp() {}
  virtual int getNumInputs() = 0;
  virtual int getNumOutputs() = 0;
  virtual void buildUserInterface(UI* ui) = 0;
  virtual int getSampleRate() = 0;
  virtual void init(int sample_rate) = 0;
  virtual void instanceInit(int sample_rate) = 0;
  virtual void instanceConstants(int sample_rate) = 0;
  virtual void instanceResetUserInterface() = 0;
  virtual void instanceClear() = 0;
  virtual FaustDsp* clone() = 0;
  virtual void metadata(Meta* m) = 0;
  virtual void compute(int count, FAUSTFLOAT** inputs, FAUSTFLOAT** outputs) = 0;
};

/* A parameter by its label ("cutoff", "Wet"…): what the route sets. At most
 * eight per class, which is more than the two filters here have. */
struct FaustParams : UI {
  static constexpr int MAX = 8;
  const char* labels[MAX];
  FAUSTFLOAT* zones[MAX];
  int n = 0;
  void addParam(const char* label, FAUSTFLOAT* zone) override {
    if (n < MAX) { labels[n] = label; zones[n] = zone; n++; }
  }
  FAUSTFLOAT* find(const char* label) const {
    for (int i = 0; i < n; i++) if (strcmp(labels[i], label) == 0) return zones[i];
    return nullptr;
  }
};
